function CatHouseRequestListCell:__init()
end

function CatHouseRequestListCell:__delete()
    self.data    = nil
    self.catData = nil
end

function CatHouseRequestListCell:Awake()
    --SetButtonAction(self.BtnFriendCollect, Bind(self, self.OnClickBtnCollectAction))
    SetButtonAction(self.BtnAccept, Bind(self, self.OnClickBtnAcceptAction))
    SetButtonAction(self.BtnRefuse, Bind(self, self.OnClickBtnRefuseAction))

    --- 训练次数上限（同时也是进化所需数量）
    self.trainTimeLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.TrainTimeLimit).num)
end

function CatHouseRequestListCell:OnDestroy()
    self:RemoveListener()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
