---FreshUI
---@param replyData table {
--- inviteId:number 申请ID
--- friend:table 好友数据 {
---   playerId:int 好友玩家Id
---   avatarId:int 头像Id
---   name:int 玩家名称
---   level:int 玩家等级
---   avatarFrame:int 头像框Id
--- }
--- playerCatId:number 猫咪唯一id
--- remainTime:number 剩余时间
---}
---@param position number
function CatHouseRequestListCell:FreshUI(replyData, position)
    ----------------------------
    --- 数据处理
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catData = component:GetCatDataById(replyData.playerCatId)
    self.data     = replyData
    self.catData  = catData
    self.position = position

    ----------------------------
    --- UI显示
    self:ShowUI(replyData, catData)

end

function CatHouseRequestListCell:ShowUI(replyData, catData)
    self:FreshCatNode(catData)
    self:FreshFriendInfo(replyData)
    --self:FreshFavoriteState(checkNumber(replyData.friend.catHouseFavorite))
    local remainTime = replyData.remainTime
    self:FreshCD(remainTime)
    if remainTime > 0 then
        self:AddListener()
    else
        self:RemoveListener()
        Events.Broadcast("CatHouseRequestListCDEnd")
    end
end

function CatHouseRequestListCell:FreshCatNode(catData)
    ---@type CatHouseListBtnNode
    local env = CfUtils.GetLuaScr(self.CatHouseListBtnNode, CatHouseListBtnNodeEnvPath)
    if isNull(env) then return end
    env:FreshCommonUI(catData)
    env:FreshTimes(self.trainTimeLimit)
    env:FreshCountdownNode()
end

function CatHouseRequestListCell:FreshFriendInfo(replyData)
    local friend = replyData.friend
    self.TextPlayerName.text = friend.name

    local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNodeEnvPath)
    if isNull(env) then return end
    env:FreshAvatarFrame(friend.friendAvatar, friend.friendAvatarFrame)
end

