--    self.BtnFriendCollect.Status = state == 0 and 1 or 2
--end

function CatHouseRequestListCell:FreshCD(seconds)
    self.TextNumber.text = GetTimeHMS2(seconds)
end

function CatHouseRequestListCell:AddListener()
    if self.__EventCatHouseTimeChange then return end
    self.__EventCatHouseTimeChange = Events.AddListener(CatHouseTimeChange, Bind(self, self.OnEventCatHouseTimeChange))
end
function CatHouseRequestListCell:RemoveListener()
    if self.__EventCatHouseTimeChange then
        Events.RemoveListener(CatHouseTimeChange, self.__EventCatHouseTimeChange)
        self.__EventCatHouseTimeChange = nil
    end
end

function CatHouseRequestListCell:PlayAnimGo(index, isInit)
    if isInit then
        CfUtils.PlayDelayShowAnimate(self.AnimRoot.gameObject, index)
    else
        CfUtils.PlayDelayShowAnimate(self.AnimRoot.gameObject, 0)
    end
end


