function CatHouseRequestListCell:OnClickBtnAcceptAction()
    local playerCatId = self.catData.id
    local catHouseMgr = CatHouseMgr:GetInstance()
    local catStatus = catHouseMgr:CheckCatActionLimit(RallySignup, playerCatId)
    if catStatus then
        local text = catHouseMgr:GetCatStateText(catStatus)
        if text then
            GameUtils.Toast(localize("该猫处于_name_,不可培育", {_name_ = text}))
        end
        return
    end

    if self.callback then
        self.callback(self.data, 1)
    end
end

function CatHouseRequestListCell:OnClickBtnRefuseAction()
    if self.callback then
        self.callback(self.data, 2)
    end
end

function CatHouseRequestListCell:OnEventCatHouseTimeChange()
    local remainTime = self.data.remainTime
    self:FreshCD(remainTime)
    if remainTime < 0 then
        self:RemoveListener()
        Events.Broadcast("CatHouseRequestListCDEnd")
    end
end

